// === Tab: mySketch ===
// Rorschach living cells
//
// Created by Nicolas Decoster for the
// topic "Winter" ❄  of #WCCChallenge
//
// Use a SDF like approach with Perlin noise and symetries.
//
// At each step:
//   * Fade out the previous content of canvas by applying
//     a mask with a small alpha.
//   * Use a large number of plotters
//   * For each plotter:
//       - go at a random position
//       - pick a Perlin noise value based on the distance/direction
//         from the center, and the time
//       - pick a color on a linear palette based on this
//         value
//       - set the plotter radius: bigger at the center of the
//         value range for the current color, smaller at color
//         transitions
//       - the plotter draw a circle at the given position, with
//         the given color and radius.

const params = {
	size: 800,
	speed: 0.0005,
	scale: 0.008,
	nSymmetries: 6,
	maxPlotterRadius: 6,
	// In frame count unit.
	cycleDuration: 500,
}

const min = (a, b) => a < b ? a : b

let colors

function initColors() {
	colors = {}

	const pink = color(255, 143, 248)
	const blue1 = color(70, 198, 255)
	const blue2 = color(45, 121, 253)
	const blue3 = color(1, 43, 210)

	colors.color1 = blue3
	colors.color2 = blue2
	colors.color3 = pink

	colors.background = color(255)
	colors.backgroundForFadeOut = color(255, 10)
}

// Get plotter characteristics from a value in [0, 1] intervall.
//
// For the plotter color, an array of colors is equally mapped
// between 0 and 1.
// 
// The plotter radius start from zero and increase to its maximum
// at the middle of the color range of values. And decreases after
// that to zero again. The idea is to have smaller plotters at
// color trransitions.
//
// Call drawPlottersPalette() to see a mapping of plotters for
// values from 0 to 1.
function getPlotter(value) {

	const palette = [
		colors.background,
		colors.background,
		colors.background,
		colors.color1,
		colors.background,
		colors.background,
		colors.color2,
		colors.background,
		colors.background,
		colors.color3,
		colors.background,
		colors.background,
		colors.color1,
		colors.background,
		colors.background,
		colors.color2,
		colors.background,
		colors.background,
		colors.color3,
		colors.background,
		colors.background,
		colors.color1,
		colors.background,
		colors.background,
		colors.background,
	]

	if (value < 0) value = 0
	if (value > 1) value = 1
	const n = palette.length
	// Size of an intervall.
	const size = 1 / n
	// Corresponding color index for the current value.
	let index = Math.floor(value/size)
	if (index < 0) {
		index = 0
	}
	if (index > n - 1) {
		index = n - 1
	}
	// Corresponding [0,1] in the current color intervall.
	// I.e. if there are 2 colors, and value is 0.6, this will
	// be 0.2. I.e size is 0.5, and 0.6 is at 20 % of the current
	// color intervall (last color).
	const valueInIntervall = (value - (index * size))/size

	// To get the radius, with fading ones on color transition.
	const center = 0.5
	const radiusScale =
				2 * (center - Math.abs(valueInIntervall - center))

	return {
		color: palette[index],
		radius: params.maxPlotterRadius * radiusScale
	}
}

// This will draw all plotters for values from 0 to 1, to see what
// they all look like.
function drawPlottersPalette() {
	const n = 100
	for (let i = 0; i < n; i++) {
		const plotter = getPlotter(i/n)
		fill(plotter.color)
		noStroke()
		const step = 5
		circle(
			50 + i*step,
			10,
			plotter.radius
		)
	}
}

function clearAll () {
	clear()
	fill(colors.background)
	noStroke()
	rect(0, 0, params.size, params.size)
}

// Apply some shadowing on each frame to fade out previous
// plots.
function fadeOut() {
	// Start a new plot every now and then.
	if (frameCount % params.cycleDuration === 0) {
		clearAll()
	}
	// Actually do the fade out.
	fill(colors.backgroundForFadeOut)
	noStroke()
	rect(0, 0, params.size, params.size)
}

// *********************************************************

function setup() {
	initColors()
	createCanvas(params.size, params.size)
	clearAll()
	// Comment to randomize the plot
	noiseSeed(1385)
}

function draw() {
	fadeOut()

	// Uncomment the following to see the plotters palette at the
	// top of the canvas.
	// drawPlottersPalette()

	const nPlotters = 4000
	for (let i = 0; i < nPlotters; i++) {
		// Pick the current plotter position, anywhere in the canvas.
		const x = Math.random() * params.size
		const y = Math.random() * params.size

		// In which plot area is this plotter?
		const area = {
			size: params.size/2
		}
		area.row = Math.floor(y / area.size)
		area.col = Math.floor(x / area.size)

		// The center of the plotter area
		area.center = {
			x: (area.col*2 + 1) * area.size/2,
			y: (area.row*2 + 1) * area.size/2,
		}

		// Get the plotter distance and direction from the center of
		// the area.
		let distanceToCenter = Math.hypot(x - area.center.x, y - area.center.y)
		let directionToCenter = Math.atan2(x - area.center.x, y - area.center.y)

		// Get the nearest branch angle. One branch for each symmetry.
		const nearestBranchAngle = (
			Math.round((directionToCenter*params.nSymmetries)/(2*Math.PI))*
			(2*Math.PI)/params.nSymmetries
		)
		const angleToNearestBranch = directionToCenter - nearestBranchAngle

		// We "project" the distance to the center on the nearest
		// branch. This is to have polygon effects instead of
		// "circle" effects.
		distanceToCenter *= Math.cos(angleToNearestBranch)

		// One of the input values for the Perlin noise field (see
		// below). This will govern the patterns along the radius
		// of the drawing.
		const distanceLike = Math.log(distanceToCenter/3)

		// Use the sin of the angle to nearest branch, also to have
		// polygon effects instead of "circle" effects.
		let distanceToNearestBranch = Math.sin(angleToNearestBranch)

		// The other input value for the Perlin noise field (see
		// below). This will govern the patterns along the "tangent"
		// of the drawing.
		//
    // Get discrete values, also to have polygon effects instead
		// of "circle" effects.
		const angleLike = Math.round(distanceToNearestBranch*5)/5

		// A seed like value, just to be sure to have a different
		// drawing on each plotting area. Warning: not a random
		// value, just a pseudo random like that won't change for
		// all plotters in the same area.
		const areaSeed = area.row*13 + area.col*41

		const timeLike = frameCount * params.speed + areaSeed

		// Get plotter properties randomly based on its "distance"
		// and "direction" to the center. In fact, those lines is
		// the part that has the most impact in the final rendering.
		let val =
			// Pick a value on a Perlin noise field. One dimension is
		  // loosely related to the distance from the center, the
			// second one loosely related the to direction to the center,
			// and the last one evolve with time.
			noise(
				distanceLike,
				angleLike,
				timeLike
			)

		// The radius of the drawing. Very small at the beginning
		// of the cycle, growing for a short time, then a fix value.
		const maxDrawingRadius = area.size/2 * 0.6
		const drawingRadius = maxDrawingRadius * min(
			1,
			(frameCount % params.cycleDuration)/(params.cycleDuration/3)
		)

		// Change the val of the plotter that are not yet to be
		// rendered.
		const bloomingFactor = min(1, 2 * distanceToCenter/drawingRadius)
		val *= bloomingFactor

		// Ok, now the val is ready, we can get the plotter properties
		// from it. Reminder: val is in [0,1] range, and its color is
		// computed on a palette that ranges from 0 to 1, and with a
		// radius that is small on color transitions.
		const plotter = getPlotter(val)

		// Plotters on branches. Here, we bypass the previous
		// computation, and force the color and radius for
		// plotters that are near the branches.
		const branchLimit = 0.02
		if (Math.abs(distanceToNearestBranch) < branchLimit) {
			plotter.color = colors.color3
			plotter.radius = 4
		}

		if (distanceToCenter > drawingRadius) {
			// Fade out the plotter outside the drawing radius
			plotter.color.setAlpha(255 - 5 * (distanceToCenter - drawingRadius))
		}

		// At last, actually plot the dot.
		fill(plotter.color)
		noStroke()
		circle(x, y, plotter.radius)
	}
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
if (typeof window.clm === 'undefined') {
    window.clm = {
        tracker: class {
            init() {}
            start() {}
            track() { return []; }
            getCurrentPosition() { return []; }
            getScore() { return 0; }
        }
    };
}
if (typeof window.ml5 === 'undefined') {
    const ml5MockObj = {
        detectStart: function() {},
        features: { get: function() { return []; } },
        on: function() {},
        ready: Promise.resolve(),
        loadModel: Promise.resolve()
    };
    window.ml5 = {
        bodypix: function() { return ml5MockObj; },
        faceapi: function() { return ml5MockObj; },
        handpose: function() { return ml5MockObj; },
        poseNet: function() { return ml5MockObj; },
        objectDetector: function() { return ml5MockObj; }
    };
}
if (typeof window.aiptag === 'undefined') { window.aiptag = {}; }
if (typeof window.lime === 'undefined') { window.lime = {}; }

// 1.8 免疫 3D 物理引擎與高階渲染 (THREE.Group, Tone.js, p5.asciify, REGL, Voronoi, PolyK, qrcode, P5Capture) 缺失導致的崩潰
if (typeof window.THREE === 'undefined') {
    window.THREE = {
        Group: class {},
        Scene: class {},
        PerspectiveCamera: class {},
        WebGLRenderer: class { setSize() {} },
        Mesh: class {},
        BoxGeometry: class {}
    };
}
if (typeof window.Tone === 'undefined') {
    window.Tone = {
        Player: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Players: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Sampler: class { triggerAttackRelease() {} connect() {} toDestination() {} },
        Sequence: class { start() {} stop() {} },
        Transport: { start: function() {}, stop: function() {}, bpm: { value: 120 } }
    };
}
if (typeof window.createREGL === 'undefined') {
    window.createREGL = function() {
        const regl = function() {};
        regl.texture = function() { return { resize: function() {} }; };
        regl.buffer = function() { return { subdata: function() {} }; };
        regl.framebuffer = function() { return { use: function(cb) { cb(); } }; };
        return regl;
    };
}
if (typeof window.Voronoi === 'undefined') {
    window.Voronoi = class {
        compute() { return { cells: [], edges: [] }; }
    };
}
if (typeof window.qrcode === 'undefined') {
    window.qrcode = function(data) {
        return {
            createImgTag: function() { return ""; },
            createTableTag: function() { return ""; },
            createSvgTag: function() { return ""; }
        };
    };
    window.qrcode.stringToBytes = function(s) { return []; };
}
if (typeof window.PolyK === 'undefined') {
    window.PolyK = {
        Slice: function() { return []; },
        Triangulate: function() { return []; },
        getArea: function() { return 0; }
    };
}
if (typeof window.P5Capture === 'undefined') {
    window.P5Capture = {
        getInstance: function() {
            return { start: function() {}, stop: function() {}, setFormat: function() {} };
        },
        setDefaultOptions: function() {}
    };
}

// 1.9 免疫 OPC (OpenProcessing Controller) 與 WebGL 內部 setUniform 崩潰
if (typeof window.OPC === 'undefined') {
    window.OPC = {
        title: function() {},
        slider: function() {},
        button: function() {},
        toggle: function() {},
        color: function() {}
    };
}
if (typeof p5 !== 'undefined' && p5.Shader) {
    const origSetUniform = p5.Shader.prototype.setUniform;
    p5.Shader.prototype.setUniform = function(name, val) {
        if (!this) return this;
        try {
            return origSetUniform.call(this, name, val);
        } catch(e) {
            return this;
        }
    };
}

// 1.95 免疫某些特定遊戲模組對 parent / maeExportApis_ 或是唯讀屬性的寫入崩潰
try {
  if (typeof window.parent !== 'undefined') {
    if (!window.parent.maeExportApis_) {
      try {
        window.parent.maeExportApis_ = function() {};
      } catch(e) {}
    }
  }
} catch(e) {}

// 1.96 免疫 textmode 缺失以及 loadSVG / p5.SVG 插件型別拋錯
if (typeof textmode === 'undefined') { window.textmode = function() {}; }
if (typeof MAT === 'undefined') { window.MAT = []; }
if (typeof SIDES === 'undefined') { window.SIDES = 4; }
if (typeof GRIDBOX === 'undefined') { window.GRIDBOX = 10; }
if (typeof COLUMNS === 'undefined') { window.COLUMNS = 5; }
if (typeof tileSize === 'undefined') { window.tileSize = 30; }
if (typeof mouseTileX === 'undefined') { window.mouseTileX = 0; }
if (typeof p5 !== 'undefined') {
  if (!p5.prototype.loadSVG) {
    p5.prototype.loadSVG = function(path, success, failure) {
      if (success) success({});
      return {};
    };
  }
  // 免疫 window.VERSION 唯讀寫入錯誤
  try {
    Object.defineProperty(window, 'VERSION', {
      value: "p5-stub",
      writable: true,
      configurable: true
    });
  } catch(e) {}
}

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || path.startsWith('http') || (path.startsWith('data:') === false && path.indexOf('.') === -1)) {
            // 當發現是遠端 URL、相對路徑或格式無副檔名時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖與 CORS 錯誤
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };

    // 修正 img.loadPixels / img.resize 缺失與未非同步載入完成呼叫
    if (!p5.Image.prototype.loadPixels) { p5.Image.prototype.loadPixels = function() { return this; }; }
    if (!p5.Image.prototype.resize) { p5.Image.prototype.resize = function() { return this; }; }
    if (!p5.Image.prototype.get) { p5.Image.prototype.get = function() { return [0,0,0,255]; }; }
    if (!p5.Image.prototype.width) {
        Object.defineProperty(p5.Image.prototype, 'width', {
            get: function() { return this._width || 1280; },
            set: function(v) { this._width = v; }
        });
    }
    if (!p5.Image.prototype.height) {
        Object.defineProperty(p5.Image.prototype, 'height', {
            get: function() { return this._height || 720; },
            set: function(v) { this._height = v; }
        });
    }

    // 修正 p5.Graphics / p5.Renderer / Element.prototype.style
    if (p5.Graphics && p5.Graphics.prototype) {
        if (!p5.Graphics.prototype.loadPixels) { p5.Graphics.prototype.loadPixels = function() { return this; }; }
    }
}

// 2.2 修正 p5.Table / loadTable / getRowCount 缺失與錯誤
if (typeof p5 !== 'undefined' && p5.Table) {
    if (!p5.Table.prototype.getRowCount) { p5.Table.prototype.getRowCount = function() { return 0; }; }
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (!this || this.width === 0 || this.height === 0) {
            return [0,0,0,255];
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return [0,0,0,255];
        }
    };
}

